mapper.select:

select 

from S02M057T
where APAPKIHONCD = #{apapkihoncd,jdbcType=VARCHAR}
  and APSHOPCD = #{apshopcd,jdbcType=VARCHAR}
  and APTOKUISAKICD = #{aptokuisakicd,jdbcType=VARCHAR}

mapper.delete:

delete from S02M057T
where APAPKIHONCD = #{apapkihoncd,jdbcType=VARCHAR}
  and APSHOPCD = #{apshopcd,jdbcType=VARCHAR}
  and APTOKUISAKICD = #{aptokuisakicd,jdbcType=VARCHAR}

mapper.select:
SELECT AP_MST.APKIHONCD AS APAPKIHONCD , AP_MST.APNM AS APAPNM , SP_MST.SHOPCD AS APSHOPCD , SP_MST.SHOPNM AS APSHOPNM , TK_MST.TOKUISAKICD AS APTOKUISAKICD , TK_MST.TOKUISAKINMN1 AS APTOKUISAKINMN1 , TK_MST.TOKUISAKIJOTAI AS APTOKUISAKIJOTAI , SYKM1.MOJISETTEIATAI AS APTOKUISAKIJOTAINM , TK_MST.JOTAISTS AS APTOKJOTAISTS , SYKM2.MOJISETTEIATAI AS APTOKJOTAISTSNM , TK_MST.SKYSAKICD AS APTOKSKYSAKICD , TK_MST.SKYSAKINMN1 AS APTOKSKYSAKINMN1 , SK_MST.SKYSAKICD AS APSKYSAKICD , SK_MST.SKYSAKINMN1 AS APSKYSAKINMN1 , NA_MST.ACIAPKIHONCD AS ACIAPKIHONCD , NA_MST.ACISHOPCD AS ACISHOPCD , TKMST.TOKUISAKICD AS ACITOKUISAKICD , TKMST.TOKUISAKINMN1 AS ACITOKUISAKINMN1 , TKMST.TOKUISAKIJOTAI AS ACITOKUISAKIJOTAI , SYKM3.MOJISETTEIATAI AS ACITOKUISAKIJOTAINM , TKMST.JOTAISTS AS ACIJOTAISTS , SYKM4.MOJISETTEIATAI AS ACIJOTAISTSNM , TKMST.SKYSAKICD AS ACISKYSAKICD , TKMST.SKYSAKINMN1 AS ACISKYSAKINMN1 , NA_MST.YUKOKBN AS YUKOKBN , NA_MST.TOSHAAPKIHONCD AS TOSHAAPKIHONCD , NA_MST.TOSHASHOPCD AS TOSHASHOPCD , NA_MST.TOSHACD AS TOSHACD , TN_MST1.TNSHAMEI AS TOSHANM , NA_MST.INPTSYSTMYMD AS INPTSYSTMYMD , NA_MST.INPTSYSTMJIKAN AS INPTSYSTMJIKAN , NA_MST.INPTUNYOYMD AS INPTUNYOYMD , NA_MST.INPTIPADRSE AS INPTIPADRSE , NA_MST.INPTPGMID AS INPTPGMID , NA_MST.KOSHAAPKIHONCD AS KOSHAAPKIHONCD , NA_MST.KOSHASHOPCD AS KOSHASHOPCD , NA_MST.KOSHACD AS KOSHACD , TN_MST2.TNSHAMEI AS KOSHANM , NA_MST.KSHNSYSTMYMD AS KSHNSYSTMYMD , NA_MST.KSHNSYSTMJIKAN AS KSHNSYSTMJIKAN , NA_MST.KSHNUNYOYMD AS KSHNUNYOYMD , NA_MST.KSHNIPADRSE AS KSHNIPADRSE , NA_MST.KSHNPGMID AS KSHNPGMID FROM S02M057T NA_MST INNER JOIN ( SELECT TK_MST.APKIHONCD , TK_MST.SHOPCD , TK_MST.TOKUISAKICD , TK_MST.TOKUISAKINMN1 , TK_MST.TOKUISAKIJOTAI , TK_MST.JOTAISTS , SK_MST.SKYSAKICD , SK_MST.SKYSAKINMN1 , SK_MST.SKYSAKINMRYAKUSHO FROM S02M013T TK_MST INNER JOIN S02M017T SK_MST ON ( TK_MST.APKIHONCD = SK_MST.APKIHONCD AND TK_MST.SHOPCD = SK_MST.SHOPCD AND TK_MST.SKYSAKICD = SK_MST.SKYSAKICD ) ) TK_MST -- 得意先マスタ ON ( NA_MST.APAPKIHONCD = TK_MST.APKIHONCD AND NA_MST.APSHOPCD = TK_MST.SHOPCD AND NA_MST.APTOKUISAKICD = TK_MST.TOKUISAKICD ) INNER JOIN S02M017T SK_MST -- 請求先マスタ ON ( NA_MST.APAPKIHONCD = SK_MST.APKIHONCD AND NA_MST.APSHOPCD = SK_MST.SHOPCD AND NA_MST.APSKYSAKICD = SK_MST.SKYSAKICD ) INNER JOIN S02M046T SP_MST -- ショップマスタ ON ( NA_MST.APAPKIHONCD = SP_MST.APKIHONCD AND NA_MST.APSHOPCD = SP_MST.SHOPCD ) INNER JOIN S02M001T AP_MST -- ＡＰ基本マスタ ON (NA_MST.APAPKIHONCD = AP_MST.APKIHONCD) INNER JOIN ( SELECT TK_MST.APKIHONCD , TK_MST.SHOPCD , TK_MST.TOKUISAKICD , TK_MST.TOKUISAKINMN1 , TK_MST.TOKUISAKIJOTAI , TK_MST.JOTAISTS , SK_MST.SKYSAKICD , SK_MST.SKYSAKINMN1 , SK_MST.SKYSAKINMRYAKUSHO FROM S02M013T TK_MST INNER JOIN S02M017T SK_MST ON ( TK_MST.APKIHONCD = SK_MST.APKIHONCD AND TK_MST.SHOPCD = SK_MST.SHOPCD AND TK_MST.SKYSAKICD = SK_MST.SKYSAKICD ) ) TKMST -- 得意先マスタ ON ( NA_MST.ACIAPKIHONCD = TKMST.APKIHONCD AND NA_MST.ACISHOPCD = TKMST.SHOPCD AND NA_MST.ACITOKUISAKICD = TKMST.TOKUISAKICD ) INNER JOIN -- ショップマスタ S02M046T SP_MST_ACI ON ( NA_MST.ACIAPKIHONCD = SP_MST_ACI.APKIHONCD AND NA_MST.ACISHOPCD = SP_MST_ACI.SHOPCD ) INNER JOIN -- ＡＰ基本マスタ S02M001T AP_MST_ACI ON (NA_MST.ACIAPKIHONCD = AP_MST_ACI.APKIHONCD) LEFT JOIN S02M003T TN_MST1 ON ( NA_MST.TOSHAAPKIHONCD = TN_MST1.APKIHONCD AND NA_MST.TOSHASHOPCD = TN_MST1.SHOPCD AND NA_MST.TOSHACD = TN_MST1.TNSHACD ) LEFT JOIN S02M003T TN_MST2 ON ( NA_MST.KOSHAAPKIHONCD = TN_MST2.APKIHONCD AND NA_MST.KOSHASHOPCD = TN_MST2.SHOPCD AND NA_MST.KOSHACD = TN_MST2.TNSHACD ) LEFT JOIN S02M006T SYKM1 ON ( SYKM1.APKIHONCD = '000' AND SYKM1.SHOPCD = '000' AND SYKM1.SETTEINO = '014' AND SYKM1.RCRDKBN = 'M' AND SYKM1.SETTEICD = TK_MST.TOKUISAKIJOTAI ) LEFT JOIN S02M006T SYKM2 ON ( SYKM2.APKIHONCD = '000' AND SYKM2.SHOPCD = '000' AND SYKM2.SETTEINO = '015' AND SYKM2.RCRDKBN = 'M' AND SYKM2.SETTEICD = TK_MST.JOTAISTS ) LEFT JOIN S02M006T SYKM3 ON ( SYKM3.APKIHONCD = '000' AND SYKM3.SHOPCD = '000' AND SYKM3.SETTEINO = '014' AND SYKM3.RCRDKBN = 'M' AND SYKM3.SETTEICD = TKMST.TOKUISAKIJOTAI ) LEFT JOIN S02M006T SYKM4 ON ( SYKM4.APKIHONCD = '000' AND SYKM4.SHOPCD = '000' AND SYKM4.SETTEINO = '015' AND SYKM4.RCRDKBN = 'M' AND SYKM4.SETTEICD = TKMST.JOTAISTS ) WHERE NA_MST.APAPKIHONCD = #{apapkihoncd,jdbcType=VARCHAR}
AND NA_MST.APSHOPCD = #{apshopcd,jdbcType=VARCHAR}
AND NA_MST.APTOKUISAKICD = #{aptokuisakicd,jdbcType=VARCHAR}

    SELECT
        COUNT(*) CNT 
    FROM
        S02M057T NA_MST 
        INNER JOIN S02M013T TK_MST 
            ON ( 
                TK_MST.APKIHONCD = NA_MST.ACIAPKIHONCD 
                AND TK_MST.SHOPCD = NA_MST.ACISHOPCD 
                AND TK_MST.TOKUISAKICD = NA_MST.ACITOKUISAKICD
            ) 
        INNER JOIN S07T001T SKZ_TBL 
            ON ( 
                SKZ_TBL.APKIHONCD = NA_MST.ACIAPKIHONCD 
                AND SKZ_TBL.SHOPCD = NA_MST.ACISHOPCD 
                AND SKZ_TBL.TOKUISAKICD = NA_MST.ACITOKUISAKICD 
                AND SKZ_TBL.SKYSAKICD = TK_MST.SKYSAKICD 
                AND SKZ_TBL.YUKOKBN = '1' 
                AND SKZ_TBL.SKYPRCSJISSIKBN = '1' 
                AND SKZ_TBL.SHIMEDYDM = #{shimedydm1,jdbcType=VARCHAR}
                AND SKZ_TBL.SHIMEDD = #{shimedd,jdbcType=VARCHAR}
            ) 
    WHERE
        NA_MST.ACIAPKIHONCD =#{apkihoncd,jdbcType=VARCHAR}
        AND NA_MST.ACISHOPCD = #{shopcd,jdbcType=VARCHAR}
        AND TK_MST.SKYSAKICD =  #{skysakicd,jdbcType=VARCHAR}
        AND NA_MST.APAPKIHONCD = #{apapkihoncd,jdbcType=VARCHAR}
        AND NA_MST.APSHOPCD = #{apshopcd,jdbcType=VARCHAR}
        AND NA_MST.APSKYSAKICD = #{apskysakicd,jdbcType=VARCHAR}
